package com.volna.inventory_service.entity;
import jakarta.persistence.*;import java.time.LocalDateTime;import java.util.UUID;
@Entity @Table(name="inventory_vendors") public class InventoryVendor { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="restaurant_id",nullable=false) UUID restaurantId; @Column(nullable=false) String name; @Column(name="contact_name") String contactName; String phone;String email;@Column(name="last_order_at") LocalDateTime lastOrderAt;boolean active=true;@Column(name="created_at",nullable=false)LocalDateTime createdAt;@Column(name="updated_at",nullable=false)LocalDateTime updatedAt;@PrePersist void c(){createdAt=updatedAt=LocalDateTime.now();}@PreUpdate void u(){updatedAt=LocalDateTime.now();}
 public Long getId(){return id;}public UUID getRestaurantId(){return restaurantId;}public void setRestaurantId(UUID v){restaurantId=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getContactName(){return contactName;}public void setContactName(String v){contactName=v;}public String getPhone(){return phone;}public void setPhone(String v){phone=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public boolean isActive(){return active;}public void setActive(boolean v){active=v;}public LocalDateTime getLastOrderAt(){return lastOrderAt;} }
